def weighted_round_robin(servers, num_requests):
    current_weights = {name: 0 for name, _ in servers}
    total_weight = sum(w for _, w in servers)
    assignments = []
    for _ in range(num_requests):
        for name, weight in servers:
            current_weights[name] += weight
        chosen = max(current_weights, key=lambda k: current_weights[k])
        current_weights[chosen] -= total_weight
        assignments.append(chosen)
    return assignments

