    table = {}
    for home, away, home_score, away_score in matches:
        for team in (home, away):
            table.setdefault(team, {"points": 0, "gd": 0})
        if home_score > away_score:
            table[home]["points"] += 3
        elif away_score > home_score:
            table[away]["points"] += 3
        else:
            table[home]["points"] += 1
            table[away]["points"] += 1
        table[home]["gd"] += home_score - away_score
        table[away]["gd"] += away_score - home_score
    ranked = sorted(table.items(), key=lambda kv: (-kv[1]["points"], -kv[1]["gd"]))
    return [name for name, _ in ranked]

