    state = "created"
    for next_state in transitions:
        if next_state not in allowed.get(state, set()):
            return f"invalid transition: {state} -> {next_state}"
        state = next_state
    return state

def rank_word_frequency(text, top_n):
    words = text.lower().split()
    freq = {}
    order = {}
    for i, w in enumerate(words):
        w = w.strip(".,!?")
        if w not in freq:
            order[w] = i
        freq[w] = freq.get(w, 0) + 1
    ranked = sorted(freq.items(), key=lambda kv: (-kv[1], order[kv[0]]))
    return ranked[:top_n]

def find_overlapping_shifts(shifts):
    conflicts = []
    sorted_shifts = sorted(shifts, key=lambda s: s[1])
    for i in range(len(sorted_shifts)):
        for j in range(i + 1, len(sorted_shifts)):
            name_i, start_i, end_i = sorted_shifts[i]
            name_j, start_j, end_j = sorted_shifts[j]
            if name_i == name_j and start_j < end_i:
                conflicts.append((name_i, (start_i, end_i), (start_j, end_j)))
    return conflicts

def order_pick_path(items_by_aisle):
    aisles = sorted(items_by_aisle.keys())
    path = []
    for idx, aisle in enumerate(aisles):
        bins = sorted(items_by_aisle[aisle])
        if idx % 2 == 1:
            bins = bins[::-1]
        for b in bins:
            path.append((aisle, b))
    return path

def process_tasks_with_aging(tasks, boost_after):
    processed = []
    remaining = [dict(t) for t in tasks]
    tick = 0
    while remaining:
        for t in remaining:
            if tick - t["submitted"] >= boost_after and t["priority"] > 1:
                t["priority"] -= 1
        remaining.sort(key=lambda t: (t["priority"], t["submitted"]))
        current = remaining.pop(0)
        processed.append(current["name"])
        tick += 1
    return processed

def has_adjacent_vip_conflict(seating_row, vip_set):
    for i in range(len(seating_row) - 1):
        if seating_row[i] in vip_set and seating_row[i+1] in vip_set:
