    for coef in coefficients:
        result = result * x + coef
    return result

def redact_digits_runs(text, min_run):
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i].isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            run_len = j - i
            if run_len >= min_run:
                result.append("*" * run_len)
            else:
                result.append(text[i:j])
            i = j
        else:
            result.append(text[i])
            i += 1
    return "".join(result)

def group_duplicate_files(files):
    def simple_hash(content):
        h = 0
        for ch in content:
            h = (h * 31 + ord(ch)) % 1000000007
        return h
    groups = {}
    for name, content in files:
        h = simple_hash(content)
        groups.setdefault(h, []).append(name)
    return sorted([sorted(g) for g in groups.values() if len(g) > 1])

def match_route(routes, path):
    path_parts = path.strip("/").split("/")
    for pattern, handler in routes:
        pattern_parts = pattern.strip("/").split("/")
        if len(pattern_parts) != len(path_parts):
            continue
        params = {}
        matched = True
        for pp, ap in zip(pattern_parts, path_parts):
            if pp.startswith(":"):
                params[pp[1:]] = ap
            elif pp != ap:
                matched = False
                break
        if matched:
            return handler, params
    return None, {}

def compare_versions(v1, v2):
    parts1 = [int(x) for x in v1.split(".")]
    parts2 = [int(x) for x in v2.split(".")]
    length = max(len(parts1), len(parts2))
    parts1 += [0] * (length - len(parts1))
    parts2 += [0] * (length - len(parts2))
    for a, b in zip(parts1, parts2):
        if a != b:
            return 1 if a > b else -1
    return 0

def detect_spikes(readings, window, threshold):
    spikes = []
    for i in range(len(readings)):
        start = max(0, i - window)
        history = readings[start:i]
        if not history:
            continue
        avg = sum(history) / len(history)
        if abs(readings[i] - avg) > threshold:
            spikes.append(i)
    return spikes

def wrap_text(words, width):
    lines = []
    current = []
    current_len = 0
    for word in words:
        extra = len(word) + (1 if current else 0)
        if current_len + extra > width:
            lines.append(" ".join(current))
            current = [word]
            current_len = len(word)
        else:
            current.append(word)
            current_len += extra
    if current:
        lines.append(" ".join(current))
    return lines

def count_palindromic_substrings_min_length(s, min_length):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i + min_length, n + 1):
            sub = s[i:j]
            if sub == sub[::-1]:
                count += 1
    return count

def nearest_warehouse(warehouses, point):
