    best_dist = None
    for name, (x, y) in sorted(warehouses.items()):
        dist = abs(x - point[0]) + abs(y - point[1])
        if best_dist is None or dist < best_dist:
            best_dist = dist
            best = name
    return best, best_dist

def dedupe_events(events, window_seconds):
    result = []
    last_seen = {}
    for event_type, ts in events:
        if event_type in last_seen and ts - last_seen[event_type] < window_seconds:
            continue
        last_seen[event_type] = ts
        result.append((event_type, ts))
    return result

def safe_transpose(matrix):
    if not matrix:
        return []
    row_len = len(matrix[0])
    for row in matrix:
        if len(row) != row_len:
            raise ValueError("Jagged matrix cannot be transposed")
    return [[matrix[r][c] for r in range(len(matrix))] for c in range(row_len)]

def merge_playlists(playlist_a, playlist_b):
    i = j = 0
    merged = []
    while i < len(playlist_a) and j < len(playlist_b):
        if playlist_a[i][1] <= playlist_b[j][1]:
            merged.append(playlist_a[i])
            i += 1
        else:
            merged.append(playlist_b[j])
            j += 1
    merged.extend(playlist_a[i:])
    merged.extend(playlist_b[j:])
    return merged

def longest_login_streak(dates):
    from datetime import datetime
    parsed = sorted(datetime.strptime(d, "%Y-%m-%d") for d in set(dates))
    longest = 1 if parsed else 0
    current = 1
    for i in range(1, len(parsed)):
        if (parsed[i] - parsed[i-1]).days == 1:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
    return longest

def bucket_students_by_grade(students):
    buckets = {"A": [], "B": [], "C": [], "D/F": []}
    for name, score in students:
        if score >= 90:
            buckets["A"].append(name)
        elif score >= 80:
            buckets["B"].append(name)
        elif score >= 70:
            buckets["C"].append(name)
        else:
            buckets["D/F"].append(name)
    averages = {}
    for grade, names in buckets.items():
        scores = [s for n, s in students if n in names]
        averages[grade] = round(sum(scores) / len(scores), 1) if scores else None
    return averages

