class FrequencyCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.store = {}
        self.freq = {}

    def put(self, key, value):
        if key in self.store:
            self.store[key] = value
            self.freq[key] += 1
            return
        if len(self.store) >= self.capacity:
            least_key = min(self.freq, key=lambda k: self.freq[k])
            del self.store[least_key]
            del self.freq[least_key]
        self.store[key] = value
        self.freq[key] = 1

    def get(self, key):
        if key not in self.store:
            return None
        self.freq[key] += 1
        return self.store[key]

def run_cache_ops(ops):
    cache = FrequencyCache(2)
    results = []
    for op in ops:
        if op[0] == "put":
            cache.put(op[1], op[2])
            results.append(None)
        else:
            results.append(cache.get(op[1]))
    return results

def find_cyclic_targets(dependencies):
    graph = {}
    for src, dst in dependencies:
        graph.setdefault(src, []).append(dst)
        graph.setdefault(dst, [])
    state = {}
    cyclic = set()

    def dfs(node, path):
        state[node] = "visiting"
        path.append(node)
        for nxt in graph.get(node, []):
            if state.get(nxt) == "visiting":
                cycle_start = path.index(nxt)
                cyclic.update(path[cycle_start:])
            elif state.get(nxt) != "done":
                dfs(nxt, path)
        path.pop()
        state[node] = "done"

    for node in list(graph):
        if state.get(node) is None:
            dfs(node, [])
    return sorted(cyclic)

def dispatch_elevator(elevator_positions, call_floor, direction):
