        digits = "".join(ch for ch in raw if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10:
            continue
        formatted = f"({digits[0:3]}) {digits[3:6]}-{digits[6:10]}"
        if formatted not in seen:
            seen.add(formatted)
            result.append(formatted)
    return result

def shipping_cost(weight_kg, distance_km):
    if weight_kg <= 1:
        base = 5.0
    elif weight_kg <= 5:
        base = 5.0 + (weight_kg - 1) * 1.5
    else:
        base = 11.0 + (weight_kg - 5) * 2.0
    if distance_km > 500:
        base *= 1.4
    elif distance_km > 100:
        base *= 1.15
    return round(base, 2)

def evaluate_expression(expr):
    tokens = []
    num = ""
    for ch in expr.replace(" ", ""):
        if ch.isdigit() or ch == ".":
            num += ch
        else:
            if num:
                tokens.append(float(num))
                num = ""
            tokens.append(ch)
    if num:
        tokens.append(float(num))

    def apply_ops(values, ops):
        b = values.pop()
        a = values.pop()
        op = ops.pop()
        if op == "+": values.append(a + b)
        elif op == "-": values.append(a - b)
        elif op == "*": values.append(a * b)
        elif op == "/": values.append(a / b)

    values, ops = [], []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2}
    for tok in tokens:
        if isinstance(tok, float):
            values.append(tok)
        else:
            while ops and precedence.get(ops[-1], 0) >= precedence.get(tok, 0):
                apply_ops(values, ops)
            ops.append(tok)
    while ops:
        apply_ops(values, ops)
    result = values[0]
    return int(result) if result == int(result) else result

def flatten_dict(d, prefix=""):
