    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

import cmath
def solve_quadratic(a, b, c):
    disc = b**2 - 4*a*c
    root1 = (-b + cmath.sqrt(disc)) / (2*a)
    root2 = (-b - cmath.sqrt(disc)) / (2*a)
    return (round(root1.real,3), round(root2.real,3)) if disc >= 0 else (str(root1), str(root2))

