def union_find_components(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    for a, b in edges:
        union(a, b)
    return len(set(find(i) for i in range(n)))

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

def trie_search_prefix(words, prefix):
    root = TrieNode()
    for w in words:
        node = root
        for ch in w:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    results = []
    def dfs(n, path):
        if n.is_end:
            results.append(prefix + path)
        for c, child in n.children.items():
            dfs(child, path + c)
    dfs(node, "")
    return sorted(results)

def majority_element(nums):
    count = 0
    candidate = None
    for n in nums:
        if count == 0:
            candidate = n
        count += 1 if n == candidate else -1
    return candidate

def reservoir_sample_deterministic(stream, k, rand_sequence):
    reservoir = stream[:k]
    for i in range(k, len(stream)):
        j = rand_sequence[i - k] % (i + 1)
        if j < k:
            reservoir[j] = stream[i]
    return reservoir

def max_subarray_with_indices(nums):
    best_sum = nums[0]
    cur_sum = nums[0]
    best_start = best_end = cur_start = 0
    for i in range(1, len(nums)):
        if cur_sum < 0:
            cur_sum = nums[i]
            cur_start = i
        else:
            cur_sum += nums[i]
        if cur_sum > best_sum:
            best_sum = cur_sum
            best_start = cur_start
            best_end = i
    return (best_sum, best_start, best_end)

def mod_pow(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

import heapq

def huffman_code_lengths(freqs):
    heap = [[f, i, [ch]] for i, (ch, f) in enumerate(freqs.items())]
    heapq.heapify(heap)
    lengths = {ch: 0 for ch in freqs}
    counter = len(heap)
    while len(heap) > 1:
        f1, _, chars1 = heapq.heappop(heap)
        f2, _, chars2 = heapq.heappop(heap)
        for ch in chars1 + chars2:
            lengths[ch] += 1
        heapq.heappush(heap, [f1 + f2, counter, chars1 + chars2])
        counter += 1
    return dict(sorted(lengths.items()))

def rabin_karp_search(text, pattern):
    n, m = len(text), len(pattern)
    if m > n:
        return -1
    base, mod = 256, 1000000007
    h = pow(base, m - 1, mod)
    p_hash = t_hash = 0
    for i in range(m):
        p_hash = (p_hash * base + ord(pattern[i])) % mod
        t_hash = (t_hash * base + ord(text[i])) % mod
    for i in range(n - m + 1):
        if p_hash == t_hash and text[i:i+m] == pattern:
            return i
        if i < n - m:
            t_hash = ((t_hash - ord(text[i]) * h) * base + ord(text[i + m])) % mod
    return -1

def collatz_length(n):
    steps = 0
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        steps += 1
    return steps

def caesar_encrypt(text, shift):
