def infix_to_postfix(expr):
    prec = {"+": 1, "-": 1, "*": 2, "/": 2}
    output = []
    ops = []
    tokens = expr.split()
    for tok in tokens:
        if tok.isdigit():
            output.append(tok)
        elif tok == "(":
            ops.append(tok)
        elif tok == ")":
            while ops and ops[-1] != "(":
                output.append(ops.pop())
            ops.pop()
        else:
            while ops and ops[-1] != "(" and prec.get(ops[-1], 0) >= prec.get(tok, 0):
                output.append(ops.pop())
            ops.append(tok)
    while ops:
        output.append(ops.pop())
    return " ".join(output)

