def recursive_fib_memo(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = recursive_fib_memo(n-1, memo) + recursive_fib_memo(n-2, memo)
    return memo[n]

