def dedupe_preserve_order(items):
    seen = set()
    out = []
    for item in items:
        key = item if isinstance(item, (int, str)) else tuple(item)
        if key not in seen:
            seen.add(key)
            out.append(item)
    return out

def merge_intervals(intervals):
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            merged[-1] = (last[0], max(last[1], end))
        else:
            merged.append((start, end))
    return merged

