class CircularBuffer:
    def __init__(self, size):
        self.size = size
        self.buf = []
    def push(self, val):
        self.buf.append(val)
        if len(self.buf) > self.size:
            self.buf.pop(0)
    def snapshot(self):
        return list(self.buf)

def drive(vals, size):
    cb = CircularBuffer(size)
    snaps = []
    for v in vals:
        cb.push(v)
        snaps.append(cb.snapshot())
    return snaps

def retry_with_backoff(attempts, fail_until):
    log = []
    for i in range(1, attempts + 1):
        if i < fail_until:
            log.append(f'attempt {i}: failed')
        else:
            log.append(f'attempt {i}: success')
            break
    else:
        log.append('exhausted')
    return log

def safe_divide_chain(nums):
    results = []
    acc = nums[0]
    for n in nums[1:]:
        try:
            acc = acc / n
        except ZeroDivisionError:
            results.append('div0')
            acc = 0
            continue
        results.append(round(acc, 3))
    return results

def running_median(values):
    import bisect
    sorted_vals = []
    medians = []
    for v in values:
        bisect.insort(sorted_vals, v)
        n = len(sorted_vals)
        if n % 2 == 1:
            medians.append(sorted_vals[n // 2])
        else:
            medians.append((sorted_vals[n // 2 - 1] + sorted_vals[n // 2]) / 2)
    return medians

def sliding_window_max(nums, k):
    from collections import deque
    dq = deque()
    result = []
    for i, n in enumerate(nums):
        while dq and nums[dq[-1]] <= n:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

def exception_chain(vals):
    out = []
    for v in vals:
        try:
            if v < 0:
                raise ValueError('negative')
            if v == 0:
                raise ZeroDivisionError('zero')
            out.append(100 / v)
        except (ValueError, ZeroDivisionError) as e:
            out.append(str(e))
        finally:
            out.append('checked')
