def bit_manipulation_stats(n):
    binary = bin(n)[2:]
    ones = binary.count('1')
    zeros = binary.count('0')
    reversed_val = int(binary[::-1], 2)
    return {'binary': binary, 'ones': ones, 'zeros': zeros, 'reversed': reversed_val}

def lru_cache_sim(capacity, ops):
    from collections import OrderedDict
    cache = OrderedDict()
    results = []
    for op in ops:
        if op[0] == 'put':
            k, v = op[1], op[2]
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > capacity:
                cache.popitem(last=False)
            results.append(None)
        else:
            k = op[1]
            if k in cache:
                cache.move_to_end(k)
                results.append(cache[k])
            else:
                results.append(-1)
    return results

