class Point:
    __match_args__ = ("x", "y")

    def __init__(self, x, y):
        self.x = x
        self.y = y


def classify(value):
    match value:
        case Point(0, 0):
            return "origin"
        case Point(x, 0) | Point(0, x):
            return ("axis", x)
        case Point(x=a, y=b) if a == b:
            return ("diagonal", a)
        case str() as s:
            return ("string", len(s))
        case [1, *rest]:
            return ("starts-one", rest)
        case {"k": v, **extra}:
            return ("mapping", v, sorted(extra))
        case (int() | float()) as n if n < 0:
            return ("negative", n)
        case _:
            return "other"


