        other.items() & {("x", [1])}
        h = "ok"
    except TypeError:
        h = "TypeError"

    i = list(zip(d.keys(), d.values())) == list(d.items())
    j = sorted(values)
    try:
        values & {1}
        k = "ok"
    except TypeError:
        k = "TypeError"
    return (a, b, c, e, f, g, h, i, j, k)

