from functools import lru_cache

@lru_cache(maxsize=None)
def digit_sum(n):
    if n < 10:
        return n
    return n % 10 + digit_sum(n // 10)

@lru_cache(maxsize=None)
def repeated_digit_sum(n):
    while n >= 10:
        n = digit_sum(n)
    return n

