def normalize_ports(tokens):
    ports = []
    for token in tokens:
        try:
            ports.append(int(token))
        except ValueError:
            ports.append(-1)
        else:
            if ports[-1] > 1024:
                ports[-1] = 1024
        finally:
            if ports[-1] == 0:
                ports.pop()
    return ports

