class SkipMultiples:
    def __init__(self, limit, n):
        self.limit = limit
        self.n = n
        self.current = 0
    def __iter__(self):
        return self
    def __next__(self):
        while self.current < self.limit:
            self.current += 1
            if self.current % self.n != 0:
                return self.current
        raise StopIteration

