        head = Node(v, head)
    return head

def reverse_recursive(node, prev=None):
    if node is None:
        return prev
    nxt = node.nxt
    node.nxt = prev
    return reverse_recursive(nxt, node)

def to_list(head):
    out = []
    while head is not None:
        out.append(head.value)
        head = head.nxt
    return out

