class InsufficientFundsError(Exception):
    pass

def process_payment(balance, amount):
    log = []
    try:
        if amount <= 0:
            raise ValueError("amount must be positive")
        if amount > balance:
            raise InsufficientFundsError(f"need {amount - balance} more")
        balance -= amount
    except ValueError as e:
        log.append(f"value_error:{e}")
    except InsufficientFundsError as e:
        log.append(f"insufficient:{e}")
    else:
        log.append(f"success:{balance}")
    finally:
        log.append("done")
    return log

def run_payments():
    return [process_payment(100, 50), process_payment(100, -5), process_payment(100, 500)]

def reconcile(events):
    stock = {}
    rejected = []
    for sku, delta in events:
        current = stock.get(sku, 0)
        if current + delta < 0:
            rejected.append((sku, delta, current))
        else:
            stock[sku] = current + delta
    return dict(sorted(stock.items())), rejected

from collections import deque

def rolling_windows(values, width):
    window = deque()
    total = 0
    result = []
    for value in values:
        window.append(value)
        total += value
        if len(window) > width:
            total -= window.popleft()
        if len(window) == width:
            result.append((window[0], window[-1], total))
    return result

def trace_aliases(mapping, names):
    result = {}
    for start in names:
        path = []
        node = start
        while node in mapping and node not in path:
            path.append(node)
            node = mapping[node]
        if node in path:
            cycle = path[path.index(node):]
            result[start] = ('cycle', tuple(cycle))
        else:
            result[start] = ('target', node)
    return result

def compact_bookings(bookings):
    merged = []
    for room, start, end in sorted(bookings):
        if merged and merged[-1][0] == room and start <= merged[-1][2]:
            old_room, old_start, old_end = merged[-1]
            merged[-1] = (old_room, old_start, max(old_end, end))
        else:
            merged.append((room, start, end))
    return merged

def session_durations(events):
    active = {}
    durations = {}
    anomalies = []
    for user, minute, action in events:
        if action == 'login':
            if user in active:
                anomalies.append((user, 'duplicate_login', minute))
            else:
                active[user] = minute
        elif action == 'logout':
            if user not in active:
                anomalies.append((user, 'orphan_logout', minute))
            else:
                durations.setdefault(user, []).append(minute - active.pop(user))
    return dict(sorted(durations.items())), anomalies, dict(sorted(active.items()))

def allocate(requests, capacities):
    remaining = capacities.copy()
    allocations = []
    for team, resource, amount in requests:
        available = remaining.get(resource, 0)
        granted = min(max(amount, 0), available)
        if granted:
            allocations.append((team, resource, granted))
            remaining[resource] = available - granted
    return allocations, dict(sorted(remaining.items()))

def coerce_rows(rows, schema):
    result = []
    errors = []
    for index, row in enumerate(rows):
        clean = {}
        for field, kind in schema.items():
            value = row.get(field)
            try:
                if kind == 'int':
                    clean[field] = int(value)
                elif kind == 'float':
                    clean[field] = round(float(value), 2)
                elif kind == 'bool':
                    lowered = str(value).lower()
                    if lowered not in ('yes', 'no'):
                        raise ValueError
                    clean[field] = lowered == 'yes'
            except (TypeError, ValueError):
                clean[field] = None
                errors.append((index, field, value))
        result.append(clean)
    return result, errors

def retry_summary(jobs, limit):
    summary = {}
    exhausted = []
    for name in sorted(jobs):
        attempts = 0
        succeeded = False
        for outcome in jobs[name][:limit]:
            attempts += 1
            if outcome:
                succeeded = True
                break
        summary[name] = (attempts, succeeded)
        if not succeeded:
            exhausted.append(name)
    return summary, exhausted

def settle(entries, overdraft_fee=5):
    balances = {}
    alerts = []
    for account, amount in entries:
        before = balances.get(account, 0)
        after = before + amount
        if amount < 0 and after < 0:
            after -= overdraft_fee
            alerts.append((account, before, amount, after))
        balances[account] = after
    return dict(sorted(balances.items())), alerts

import copy

def apply_patches(document, patches):
    result = copy.deepcopy(document)
    applied = []
    rejected = []
    for path, value in patches:
        keys = path.split('.')
        current = result
        valid = True
        for key in keys[:-1]:
            if key not in current:
                current[key] = {}
            if not isinstance(current[key], dict):
                valid = False
                break
            current = current[key]
        if valid:
            current[keys[-1]] = value
            applied.append(path)
        else:
            rejected.append(path)
    return result, applied, rejected
